# Generated by build.py from recipe.yml for recipe smtp-see-why-mail-was-refused. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'report.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Nightly report`n`nAll 42 jobs finished. None failed.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'why-refused.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Usage: sh why-refused.sh LOG. Finds the last SMTP exchange in surl's -v log, waits (at most`n# 10 s) until surl has ended it, then prints each refusal in it, a reply of 4xx or 5xx, with`n# the two lines before it: the command and surl's reason.`nlog=`$1`nn=`$(grep 'opened: smtp' `"`$log`" | tail -n 1 | sed 's/^#\([0-9]*\) .*/\1/')`ntries=0`nuntil grep -q `"^#`$n \* Exchange `$n ended`" `"`$log`"; do`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -gt 10 ]; then echo `"exchange `$n has not ended`" >&2; exit 1; fi`n  sleep 1`ndone`ngrep -B 2 -E `"^#`$n > [45][0-9][0-9] `" `"`$log`" | grep `"^#`$n `" | sed -e 's/^#[0-9]* //' -e 's/\\r\\n`$//'`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'mail.log', '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', '--mailbox', '"ops@example.com:opspass;quota=200"', '--mailbox', 'app@example.com:apppass', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh why-refused.sh mail.log } finally { Stop-Process $server0 }
